import{z as n,x as d,o,c as i,q as B,j as l,D as s,d as a,s as t,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"FUSE","description":"","frontmatter":{"title":"FUSE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fuse.md","filePath":"cs/fuse.md","lastUpdated":1791413859000}'),F={name:"cs/fuse.md"};function p(f,E,u,S,c,D){const r=d("Mermaid");return o(),i("div",null,[E[2]||(E[2]=B('<h1 id="fuse" tabindex="-1">FUSE <a class="header-anchor" href="#fuse" aria-label="Permalink to &quot;FUSE&quot;">​</a></h1><div class="epigraph"><p>FUSE 把 VFS 操作编成发往用户守护进程的请求；真正的 lookup/read 在用户态完成，再把结果填回内核页缓存。</p><footer>—— 据 Szeredi, FUSE；Linux fuse 文档；Vangoor, Tarasov, Zadok 对 FUSE 性能的测量</footer></div><p><a href="/cs/overlayfs">上一课</a>仍在内核里叠两棵内核 FS。<a href="/cs/vfs">VFS</a> 的操作表也可以指向一个<strong>把请求送出内核</strong>的驱动。缺口是 FUSE：让 sshfs、ntfs-3g、用户态实验 FS 不必进内核树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核实现新 FS 要模块、许可证、崩溃半径。FUSE：内核模块登记 fuse 超级块；用户守护进程通过 <code>/dev/fuse</code> 读请求、写应答。read 可能两次拷贝（内核到守护、守护到内核页）。缺口：请求类型（lookup、open、read、write、setattr）、多线程守护、以及 <code>cache_readdir</code> 与内核 <a href="/cs/dcache">dcache</a> / <a href="/cs/page-cache">页缓存</a> 如何可选地缓存用户态结果。</p><p><span class="marginnote">deadlock：守护进程自己再访问同一挂载点会卡住。解决方案是克隆线程、或 <code>fuse_conn</code> 的 abort。本课不写 libfuse API 教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户 <code>open</code>：VFS → fuse → 队列 → 守护 <code>open</code> 回调 → 返回句柄。<code>read</code>：内核或可把请求与页一起交给守护，守护填缓冲，内核插入页树。写路径类似，fsync 变成用户态 fsync。对照 overlay：联合可以在用户态做（unionfs-fuse），慢但可实验。对照内核 ext4：没有系统调用往返。</p><p><span class="marginnote">直觉类比：FUSE 像把仓库盘点外包——内核前台只负责接单转发，真正干活的是一个外面的普通进程。好处是外包公司倒闭（守护崩溃）不砸前台（内核），坏处是每张单子都要递出大门跑一趟。</span></p>',9)),(o(),l(A,null,{default:s(()=>[t(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%20--%3E%20VFS%5B%22VFS%22%5D%0A%20%20VFS%20--%3E%20DEV%5B%22%2Fdev%2Ffuse%20%E8%AF%B7%E6%B1%82%22%5D%0A%20%20DEV%20--%3E%20DAEM%5B%22%E7%94%A8%E6%88%B7%E5%AE%88%E6%8A%A4%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20DAEM%20--%3E%20DEV%0A%20%20DEV%20--%3E%20PAGE%5B%22%E5%8F%AF%E9%80%89%E5%A1%AB%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:s(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"FUSE 把文件系统变成普通进程：可用脚本语言、可调试、崩溃不带倒内核（挂载点会 I/O 错误）。税是上下文切换与拷贝。不要把 FUSE 写成数据库用户态存储引擎综述：接口仍是 POSIX 文件，不是 SQL。",-1)),E[5]||(E[5]=e("p",null,[a("安全：挂载通常允许用户在自己的目录上 "),e("code",null,"fusermount"),a("，节点由 MNT_NOSUID 等限制；这是策略，对象仍是请求协议。")],-1)),E[6]||(E[6]=e("p",null,[a("实现上：FUSE 的 daemon 若单线程且再访问同一挂载点，会自死锁。内核可 abort 连接把等待者唤醒为 ENODEV。writeback 缓存开启时语义更像本地 FS，关闭则更像严格 RPC。 读法上只引用"),e("a",{href:"/cs/overlayfs"},"上一课"),a("的结论，不把对象换成训练推理或限价簿。")],-1)),E[7]||(E[7]=e("p",null,"单线程守护为什么会把自己锁死？死循环出在「回答请求的人又去发请求」。",-1)),(o(),l(A,null,{default:s(()=>[t(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E7%94%A8%E6%88%B7%E7%A8%8B%E5%BA%8F%E8%AE%BF%E9%97%AE%20fuse%20%E6%8C%82%E8%BD%BD%E7%82%B9%22%5D%20--%3E%20KER%5B%22%E5%86%85%E6%A0%B8%E6%8A%8A%E8%AF%B7%E6%B1%82%E6%94%BE%E8%BF%9B%20%2Fdev%2Ffuse%20%E9%98%9F%E5%88%97%22%5D%0A%20%20KER%20--%3E%20DAEM%5B%22%E5%8D%95%E7%BA%BF%E7%A8%8B%E5%AE%88%E6%8A%A4%E8%BF%9B%E7%A8%8B%E5%8F%96%E5%87%BA%E8%AF%B7%E6%B1%82%22%5D%0A%20%20DAEM%20--%3E%20SELF%5B%22%E5%9B%9E%E8%B0%83%E9%87%8C%E5%8F%88%E8%AE%BF%E9%97%AE%E5%90%8C%E4%B8%80%E6%8C%82%E8%BD%BD%E7%82%B9%22%5D%0A%20%20SELF%20--%3E%20AGAIN%5B%22%E7%94%9F%E6%88%90%E6%96%B0%E7%9A%84%20fuse%20%E8%AF%B7%E6%B1%82%E6%8E%92%E9%98%9F%22%5D%0A%20%20AGAIN%20--%3E%20WAIT%5B%22%E5%AE%88%E6%8A%A4%E8%BF%9B%E7%A8%8B%E5%8E%BB%E7%AD%89%E8%BF%99%E4%B8%AA%E6%96%B0%E8%AF%B7%E6%B1%82%22%5D%0A%20%20WAIT%20--%3E%20STUCK%5B%22%E6%97%A7%E8%AF%B7%E6%B1%82%E6%B0%B8%E8%BF%9C%E6%B2%A1%E4%BA%BA%E5%BA%94%E7%AD%94%EF%BC%9A%E5%8D%A1%E6%AD%BB%22%5D%0A%20%20FIX%5B%22%E8%A7%A3%E6%B3%95%EF%BC%9A%E5%85%8B%E9%9A%86%E7%BA%BF%E7%A8%8B%E6%88%96%E5%86%85%E6%A0%B8%20abort%20%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20STUCK%0A"})]),fallback:s(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=B('<p><span class="marginnote">术语翻译：「上下文切换的税」指每次文件操作都要在内核、守护进程之间来回切换并拷贝数据。一次 4 KB 的 read 至少多出 2 次数据拷贝和多次内核/用户态往返——这就是 FUSE 比内核文件系统慢的主因。</span></p><p><span class="marginnote">为什么重要：理解「崩溃半径」这个卖点——内核态文件系统出段错误就是整个系统 panic，而 FUSE 守护进程崩了只是挂载点上的访问变成 I/O 错误，系统照常运行。实验性文件系统因此敢于先在用户态写。</span></p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>FUSE</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 virtio-fs、fuse-bpf 的全部加速路径。不保证与 <a href="/cs/lsm-selinux">SELinux</a> 标签透传的每一种组合。下一课把「文件在另一台机器」的语义裂缝钉住：NFS 的缓存与关闭-打开一致性。</p><p>版本字段会变，课序钉的是机制对象「FUSE」，不是某一主线内核的结构体名。 后课默认：VFS 操作可以出核。远程文件语义与本地 POSIX 差在哪，下一课 NFS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FUSE 用 <code>/dev/fuse</code> 把 VFS 请求交给用户态。</li><li>可缓存进 dcache/页缓存，默认仍有往返税。</li><li>远程语义是下一课。</li><li>出处：Linux fuse 文档；Vangoor et al. 对 FUSE 性能；Szeredi。</li></ul>',9))])}const T=n(F,[["render",p]]);export{h as __pageData,T as default};
